import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/cooking/corelib-actions.md","filePath":"modules/cooking/corelib-actions.md","lastUpdated":0}`),a={name:`modules/cooking/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to “CoreLib 动作”">​</a></h1><p>EmakiCooking 启用后会向 CoreLib 动作注册表追加营养值、阈值复查和配方奖励段。它们可用于其他模块的动作列表、CoreLib 管道模板，或第三方通过 CoreLib 管道引擎触发的管道。</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>本页只记录 EmakiCooking 注册的段；CoreLib 自带通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>。当前段 ID 只使用下表中的规范名，不再提供历史别名入口。旧的 <code>emakicookingaddnutrition</code> 现在写作 <code>cooking_add_nutrition</code>，其余同理。</p></div><h2 id="段-id" tabindex="-1">段 ID <a class="header-anchor" href="#段-id" aria-label="Permalink to “段 ID”">​</a></h2><p>七个段的目标要求都是 <code>REQUIRED_ENTITY</code>，非玩家目标会跳过。</p><table tabindex="0"><thead><tr><th>段 ID</th><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>cooking_add_nutrition</code></td><td>增加营养值</td><td>增加指定营养类型当前值。</td></tr><tr><td><code>cooking_remove_nutrition</code></td><td>扣除营养值</td><td>扣除指定营养类型当前值。</td></tr><tr><td><code>cooking_set_nutrition</code></td><td>设置营养值</td><td>设置指定营养类型当前值。</td></tr><tr><td><code>cooking_clear_nutrition</code></td><td>清空营养值</td><td>将指定类型或全部类型设为各自 <code>min</code>。</td></tr><tr><td><code>cooking_reset_nutrition</code></td><td>重置营养值</td><td>将指定类型或全部类型设为各自 <code>default</code>。</td></tr><tr><td><code>cooking_recheck_nutrition_threshold</code></td><td>复查阈值</td><td>重新评估目标玩家的单项与组合营养阈值。</td></tr><tr><td><code>cooking_run_recipe_reward</code></td><td>执行配方奖励</td><td>通过 CookingRewardService 执行已加载配方的某个结果分支。</td></tr></tbody></table><p>「作用于谁」由 source 决定，不再有 <code>target</code> 参数：作用于执行者自己写 <code>self</code>，指定玩家用 <code>player_by_name</code>。</p><h2 id="营养增减与设置" tabindex="-1">营养增减与设置 <a class="header-anchor" href="#营养增减与设置" aria-label="Permalink to “营养增减与设置”">​</a></h2><p><code>cooking_add_nutrition</code>、<code>cooking_remove_nutrition</code>、<code>cooking_set_nutrition</code> 共用同一组参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td>STRING</td><td>是</td><td>—</td><td>营养类型 ID。</td></tr><tr><td><code>amount</code></td><td>EXPRESSION</td><td>是</td><td>—</td><td>营养数值，可写 CoreLib 表达式。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_add_nutrition type=satiety amount=5&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_remove_nutrition type=hydration amount=3&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | cooking_set_nutrition type=hydration amount=80&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # amount 写成表达式</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_add_nutrition type=satiety amount=%var.base%*1.5&#39;</span></span></code></pre></div><p>成功时输出 <code>type</code>、<code>old_value</code>、<code>new_value</code>。<code>type</code> 写成空白会在运行时以 <code>INVALID_CONFIG</code> 失败；营养服务拒绝这次操作时以 <code>REJECTED</code> 失败并带上原因。</p><h2 id="清空与重置营养" tabindex="-1">清空与重置营养 <a class="header-anchor" href="#清空与重置营养" aria-label="Permalink to “清空与重置营养”">​</a></h2><p><code>cooking_clear_nutrition</code> 把营养值设为对应类型的 <code>min</code>；<code>cooking_reset_nutrition</code> 设为对应类型的 <code>default</code>。两者的区别在语义上：一个把玩家饿到底，一个把玩家还原到中性状态。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>营养类型 ID；为空时处理全部已注册类型。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_clear_nutrition type=hydration&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | cooking_reset_nutrition&#39;</span></span></code></pre></div><p><code>type</code> 指向未注册的类型时以 <code>INVALID_CONFIG</code> 失败；没有任何已注册类型时跳过。遇到第一个失败的类型就停止，不会留下改了一半的营养记录。</p><h2 id="阈值复查" tabindex="-1">阈值复查 <a class="header-anchor" href="#阈值复查" aria-label="Permalink to “阈值复查”">​</a></h2><p><code>cooking_recheck_nutrition_threshold</code> 重新评估目标玩家的营养阈值。无参数。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_recheck_nutrition_threshold&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | cooking_recheck_nutrition_threshold&#39;</span></span></code></pre></div><p>营养系统未启用或该玩家还没有缓存记录时按跳过处理，这两种情况都不算故障。</p><h2 id="配方奖励" tabindex="-1">配方奖励 <a class="header-anchor" href="#配方奖励" aria-label="Permalink to “配方奖励”">​</a></h2><p><code>cooking_run_recipe_reward</code> 会查找已加载配方，并通过 CookingRewardService 的统一出口发放产物、执行结果动作。它不会临时构造新配方；<code>recipe</code> 必须已经由对应工位加载器加载。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>recipe</code></td><td>STRING</td><td>是</td><td>—</td><td>配方 ID。</td></tr><tr><td><code>station</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>工位目录名；为空时遍历所有工位加载器。</td></tr><tr><td><code>outcome</code></td><td>STRING</td><td>否</td><td><code>success</code></td><td>结果名或路径，如 <code>success</code>、<code>perfect</code>、<code>result.success</code>。不含 <code>.</code> 时自动补成 <code>result.&lt;名字&gt;</code>。</td></tr><tr><td><code>drop_result</code></td><td>BOOLEAN</td><td>否</td><td><code>false</code></td><td>是否把产物掉落在目标位置，而不是进入背包。</td></tr><tr><td><code>include_outputs</code></td><td>BOOLEAN</td><td>否</td><td><code>true</code></td><td>是否发放结果分支中的 <code>outputs</code>。</td></tr><tr><td><code>include_actions</code></td><td>BOOLEAN</td><td>否</td><td><code>true</code></td><td>是否执行结果分支中的 <code>actions</code>。</td></tr><tr><td><code>phase</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>记录在嵌套动作上的阶段名；为空时自动生成为 <code>cooking.action.recipe.&lt;配方 ID&gt;</code>。</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | cooking_run_recipe_reward recipe=apple_pie station=oven outcome=success&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cooking_run_recipe_reward recipe=tea outcome=result.perfect drop_result=true include_actions=false&#39;</span></span></code></pre></div><p><code>recipe</code> 为空、<code>station</code> 不是已知工位、配方查不到，都会以 <code>INVALID_CONFIG</code> 失败。结果分支既没有 <code>outputs</code> 也没有 <code>actions</code>（或两个开关都关掉）时按跳过处理。成功时输出 <code>recipe</code>、<code>station</code>、<code>outcome</code>、<code>outputs</code>、<code>actions</code>、<code>target</code>。</p><p>奖励链是异步且不等待结果的，所以这个段成功只代表发放已提交，不代表已完成。嵌套的配方动作运行在这个段没有构建的上下文里，管道的上下文声明检查不会延伸进去。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li><code>amount</code> 声明为 EXPRESSION，参数文本里的占位符会先被渲染再交给表达式引擎求值，所以 <code>%var.*%</code>、模块写入的上下文占位符与 PlaceholderAPI 占位符都能直接参与运算。</li><li>营养服务或配方奖励服务未就绪时，对应段以 <code>MISSING_CONTEXT</code> 失败而不是静默跳过。</li><li>嵌套配方动作可见的占位符包括 <code>recipe_id</code>、<code>recipe_name</code>、<code>station_type</code>，以及带 <code>cooking_</code> 前缀的同名写法和 <code>cooking_outcome</code>。</li></ul>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};